; _xcall_main: shared cross-bank trampoline for non-banked callers
_xcall_main:
    STA _xcall_vector
    STX _xcall_vector+1
    LDY #$00
    PLA
    STA ($82),Y
    INC $82
    BNE _L0114
    INC $83
_L0114:
    PLA
    STA ($82),Y
    INC $82
    BNE _L0115
    INC $83
_L0115:
    LDA $D301
    STA ($82),Y
    INC $82
    BNE _L0116
    INC $83
_L0116:
    LDA $D301
    AND #$E3
    ORA $88
