    LDA #>_xcall_main_resume_m1
    PHA
    LDA #<_xcall_main_resume_m1
    PHA
    LDA _xcall_vector+1
    PHA
    LDA _xcall_vector
    SEC
    SBC #$01
    PHA
    BCS _xcall_main_no_borrow
    PLA
    TAX
    PLA
    SEC
    SBC #$01
    PHA
    TXA
    PHA
_xcall_main_no_borrow:
    RTS
_xcall_main_resume_m1:
    NOP
_xcall_main_resume:
    PHA
    TXA
    PHA
    TYA
    PHA
    LDY #$00
    LDA $82
    SEC
    SBC #$01
    STA $82
